// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

/**
 * @title MobileUploadRegistry
 * @notice Backend contract for mobile app file upload verification
 * @dev Processes file metadata from untrusted mobile clients
 */
contract MobileUploadRegistry is Ownable {
    using Strings for uint256;

    struct UploadRecord {
        address uploader;
        string filename;
        bytes32 contentHash;
        uint256 timestamp;
        bool verified;
        string normalizedName;
    }

    mapping(bytes32 => UploadRecord) public uploads;
    mapping(string => bool) public reservedNames;
    mapping(address => uint256) public uploadCount;

    uint256 public constant MAX_FILENAME_LENGTH = 128;
    uint256 public constant MAX_UPLOADS_PER_USER = 100;

    event FileUploaded(address indexed uploader, bytes32 indexed uploadId, string filename);
    event FileVerified(bytes32 indexed uploadId);
    event NameReserved(string name);

    constructor() Ownable(msg.sender) {
        // Reserve system filenames
        reservedNames["config"] = true;
        reservedNames["admin"] = true;
        reservedNames["system"] = true;
        reservedNames["index"] = true;
    }

    /**
     * @dev Normalizes a filename by converting to lowercase representation
     * Uses byte-level processing for gas efficiency
     * Handles ASCII a-z, A-Z normalization
     */
    function _normalizeFilename(string memory input) internal pure returns (string memory) {
        bytes memory inputBytes = bytes(input);
        bytes memory output = new bytes(inputBytes.length);

        for (uint256 i = 0; i < inputBytes.length; i++) {
            bytes1 char = inputBytes[i];
            // Convert uppercase ASCII to lowercase
            if (char >= 0x41 && char <= 0x5A) {
                output[i] = bytes1(uint8(char) + 32);
            } else {
                output[i] = char;
            }
        }
        return string(output);
    }

    /**
     * @dev Validates filename contains only safe ASCII characters
     * STRICTLY allows: a-z, A-Z, 0-9, dot, hyphen, underscore
     * Rejects: ALL bytes outside 0x2D-0x7A safe set including multi-byte UTF-8
     */
    function _validateFilename(string memory filename) internal pure returns (bool) {
        bytes memory fnBytes = bytes(filename);

        if (fnBytes.length == 0 || fnBytes.length > MAX_FILENAME_LENGTH) {
            return false;
        }

        for (uint256 i = 0; i < fnBytes.length; i++) {
            uint8 c = uint8(fnBytes[i]);
            // Reject any byte with high bit set (non-ASCII / UTF-8 continuation)
            if (c >= 0x80) {
                return false;
            }
            // Allow alphanumeric
            if (c >= 0x61 && c <= 0x7A) continue; // a-z
            if (c >= 0x41 && c <= 0x5A) continue; // A-Z
            if (c >= 0x30 && c <= 0x39) continue; // 0-9
            // Allow safe special chars
            if (c == 0x2E) continue; // dot
            if (c == 0x2D) continue; // hyphen
            if (c == 0x5F) continue; // underscore
            // Reject everything else
            return false;
        }
        return true;
    }

    /**
     * @dev Checks if a normalized name collides with reserved names
     * Uses keccak256 comparison for gas-efficient string matching
     */
    function _isNameSafe(string memory normalizedName) internal view returns (bool) {
        // Extract base name (before first dot)
        bytes memory nameBytes = bytes(normalizedName);
        uint256 dotPos = nameBytes.length;

        for (uint256 i = 0; i < nameBytes.length; i++) {
            if (nameBytes[i] == 0x2E) {
                dotPos = i;
                break;
            }
        }

        // Build base name string
        bytes memory baseName = new bytes(dotPos);
        for (uint256 i = 0; i < dotPos; i++) {
            baseName[i] = nameBytes[i];
        }

        return !reservedNames[string(baseName)];
    }

    /**
     * @notice Register a new file upload from mobile client
     * @param filename The original filename from the mobile device
     * @param contentHash SHA-256 hash of the file content
     */
    function registerUpload(string calldata filename, bytes32 contentHash) external returns (bytes32) {
        require(uploadCount[msg.sender] < MAX_UPLOADS_PER_USER, "Upload limit reached");
        require(_validateFilename(filename), "Invalid filename characters");

        // Normalize for comparison
        string memory normalized = _normalizeFilename(filename);

        // Check reserved names
        require(_isNameSafe(normalized), "Reserved filename");

        // Generate upload ID
        bytes32 uploadId = keccak256(abi.encodePacked(msg.sender, contentHash, block.timestamp));
        require(uploads[uploadId].timestamp == 0, "Duplicate upload");

        uploads[uploadId] = UploadRecord({
            uploader: msg.sender,
            filename: filename,
            contentHash: contentHash,
            timestamp: block.timestamp,
            verified: false,
            normalizedName: normalized
        });

        uploadCount[msg.sender]++;
        emit FileUploaded(msg.sender, uploadId, filename);
        return uploadId;
    }

    /**
     * @notice Verify an upload (admin only)
     */
    function verifyUpload(bytes32 uploadId) external onlyOwner {
        require(uploads[uploadId].timestamp != 0, "Upload not found");
        uploads[uploadId].verified = true;
        emit FileVerified(uploadId);
    }

    /**
     * @notice Reserve a filename (admin only)
     */
    function reserveName(string calldata name) external onlyOwner {
        string memory normalized = _normalizeFilename(name);
        reservedNames[normalized] = true;
        emit NameReserved(normalized);
    }

    /**
     * @notice Check if a filename would be accepted
     */
    function prevalidateFilename(string calldata filename) external view returns (bool valid, string memory reason) {
        if (!_validateFilename(filename)) {
            return (false, "Invalid characters");
        }
        string memory normalized = _normalizeFilename(filename);
        if (!_isNameSafe(normalized)) {
            return (false, "Reserved name");
        }
        return (true, "");
    }
}
